package com.example.erp.config;
import com.example.erp.model.Models.*;import com.example.erp.repo.Repos.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeed{@Bean CommandLineRunner seed(UserRepo u,InventoryRepo i,PasswordEncoder e){return a->{if(u.count()==0){for(String[] x:new String[][]{{"admin","ADMIN","Pune"},{"ops","OPERATIONS_USER","Pune"},{"sales","SALES_USER","Pune"}}){User z=new User();z.username=x[0];z.password=e.encode("password");z.role=x[1];z.location=x[2];u.save(z);}}if(i.count()==0){Inventory x=new Inventory();x.item="Item A";x.category="Raw Material";x.location="Pune";x.batch="B1";x.physicalQuantity=100;x.reservedQuantity=0;i.save(x);Inventory y=new Inventory();y.item="Item A";y.category="Raw Material";y.location="Mumbai";y.batch="B1";y.physicalQuantity=200;y.reservedQuantity=0;i.save(y);}};}}
